                "end": 944
              },
              "role": "callee"
            }
          ],
          "resolution_status": "resolved",
          "resolution_error": "",
          "resolution_method": "grep_fallback"
        }
      },
      "checklist_file": "outputs/02c_PARTIAL_W1B26_1771298811.json",
      "property_id": "PROP-0015"
    },
    {
      "check_id": "CHK-PROP-0016-001",
      "checklist_item": {
        "check_id": "CHK-PROP-0016-001",
        "property_id": "PROP-0016",
        "title": "Does copy_trie produce a completely independent copy where modifications to one do not affect the other?",
        "severity": "High",
        "mindset": "Formal Verification Engineer",
        "is_boundary_check": false,
        "reachability": {
          "classification": "external-reachable",
          "entry_points": [
            "Transaction"
          ],
          "attacker_controlled": true,
          "bug_bounty_scope": "in-scope"
        },
        "test_procedure": "1. Create trie T1 with entries, then copy to T2 = copy_trie(T1).\n2. Modify T2 by adding/removing/updating entries.\n3. Verify T1._data is unchanged (compare before/after snapshots).\n4. Modify T1 and verify T2._data is unchanged.\n5. Test isolation of all trie attributes (secured, default, etc.).",
        "bug_class": "State Consistency",
        "risk_category": "Tampering",
        "notes": "Source: PROP-0016, Invariant: INV-005. Shallow copy aliasing = broken state reverts.",
