      "checklist_item": {
        "check_id": "CHK-PROP-0018-001",
        "property_id": "PROP-0018",
        "title": "Does trie_set with default value correctly delete existing keys from trie._data?",
        "severity": "High",
        "mindset": "Formal Verification Engineer",
        "is_boundary_check": false,
        "reachability": {
          "classification": "external-reachable",
          "entry_points": [
            "Transaction"
          ],
          "attacker_controlled": true,
          "bug_bounty_scope": "in-scope"
        },
        "test_procedure": "1. Set key K to non-default value V.\n2. Verify K is in trie._data.\n3. Set key K to trie.default (deletion operation).\n4. Verify K is NOT in trie._data (use 'in' operator).\n5. Verify trie_get(K) returns trie.default after deletion.",
        "bug_class": "State Consistency",
        "risk_category": "Tampering",
        "notes": "Source: PROP-0018, Invariant: INV-007. Failed deletion = ghost entries = incorrect root.",
        "code_scope": {
          "locations": [
            {
